class string_buf;

class stringx {
    char *chars;
    string_buf *my_buf;

public:
    stringx();
    stringx(const stringx &);
    ~stringx();
    stringx &operator=(const stringx &);
    void to_lower();
};

class filespec {
public:
    stringx path;
    stringx name;
    stringx ext;

    explicit filespec(const stringx &);
};

enum entity_flavor_t {
    ENTITY_CAMERA,
    ENTITY_ENTITY,
    ENTITY_MARKER,
    ENTITY_MIC,
    ENTITY_LIGHT_SOURCE,
    ENTITY_PARTICLE_GENERATOR,
    ENTITY_PHYSICAL,
    ENTITY_ITEM,
    ENTITY_LIGHT,
    ENTITY_MOBILE,
    ENTITY_CONGLOMERATE,
    ENTITY_TURRET,
    ENTITY_BEAM,
    ENTITY_SCANNER,
    ENTITY_MORPHABLE_ITEM,
    ENTITY_SKY,
    ENTITY_MANIP,
    ENTITY_SWITCH,
    ENTITY_BOX_TRIGGER
};

class entity {
    char data[0x7c];
    entity_flavor_t flavor;

public:
    entity_flavor_t get_flavor() const { return flavor; }
};

template<class T> class my_allocator;

template<class T, class Allocator = my_allocator<T> >
class vector {
    T *start;
    T *finish;
    T *end_of_storage;

    void _M_insert_aux(T *position, const T &value);

public:
    void push_back(const T &value) {
        if (finish != end_of_storage) {
            new (finish) T(value);
            ++finish;
        } else {
            _M_insert_aux(finish, value);
        }
    }
};

class world_dynamics_system {
public:
    class entity_preload_pair {
    public:
        entity_preload_pair(entity *e, const stringx &ent_name) {
            ent = e;
            name = ent_name;
        }
        entity_preload_pair(const entity_preload_pair &b) {
            ent = b.ent;
            name = b.name;
        }

        entity *ent;
        stringx name;
    };

private:
    char data[0x394];
    vector<entity_preload_pair> entity_preloads;

public:
    void add_entity_preload_script(entity *e, const stringx &entity_name);
};

void world_dynamics_system::add_entity_preload_script(entity *e, const stringx &entity_name)
{
	switch(e->get_flavor())
	{
    case ENTITY_CAMERA:
    case ENTITY_MARKER:
    case ENTITY_MIC:
    case ENTITY_LIGHT_SOURCE:
    case ENTITY_PARTICLE_GENERATOR:
    case ENTITY_LIGHT:
    case ENTITY_BOX_TRIGGER:
		break;

    default:
		{
			stringx name = entity_name;
			name.to_lower();
			filespec spec(name);

			entity_preloads.push_back(entity_preload_pair(e, spec.name));
		}
		break;
	}
}
